script:
// Rede Wi-Fi (OpenWrt) — SSIDs, roaming, mesh e canais de vários roteadores.
//
// O NetMonitor guarda a configuração desejada (device.settings: a da rede e o
// ajuste deste roteador) e este script a leva ao UCI. Só as seções `nm_*`
// pertencem ao plugin: as demais redes do roteador são lidas, nunca
// alteradas. Aplicar faz backup, confere o resultado e restaura sozinho se o
// roteador não ficar como deveria.

// ---------------------------------------------------------------- leitura

fn unquote(raw) {
    let v = trimmed(raw);
    if v.len() >= 2 && v.starts_with("'") && v.ends_with("'") {
        v = v.sub_string(1, v.len() - 2);
    }
    v.replace("'\\''", "'");
    v
}

// `uci show wireless` → #{ seção: #{ kind, options } }.
fn read_wireless(device) {
    let sections = #{};
    for line in lines(device.run("uci show wireless")) {
        let sec = regex_groups(line, "^wireless\\.([^.=]+)=([A-Za-z0-9_-]+)$");
        if sec != () {
            sections[sec[0]] = #{ kind: sec[1], options: #{} };
            continue;
        }
        let opt = regex_groups(line, "^wireless\\.([^.=]+)\\.([^=]+)=(.*)$");
        if opt != () && sections.contains(opt[0]) {
            sections[opt[0]].options[opt[1]] = unquote(opt[2]);
        }
    }
    sections
}

fn band_of(options) {
    if options.contains("band") { return options.band; }
    let hw = options.hwmode ?? "";
    if hw == "11a" { return "5g"; }
    let ch = options.channel ?? "auto";
    if ch != "auto" && parse_int(ch) > 14 { return "5g"; }
    "2g"
}

fn band_label(band) {
    if band == "2g" { return "2,4 GHz"; }
    if band == "5g" { return "5 GHz"; }
    if band == "6g" { return "6 GHz"; }
    band
}

// Banda → o primeiro rádio dela.
fn radios_by_band(sections) {
    let found = #{};
    for name in sections.keys() {
        let section = sections[name];
        if section.kind == "wifi-device" {
            let band = band_of(section.options);
            if !found.contains(band) { found[band] = name; }
        }
    }
    found
}

fn runtime_status(device) {
    let r = device.ssh("ubus call network.wireless status");
    if r.exit != 0 || trimmed(r.stdout) == "" { return #{}; }
    json_parse(r.stdout)
}

fn ifname_of(rt, section) {
    for radio in rt.keys() {
        for iface in rt[radio].interfaces ?? [] {
            if iface.section == section { return iface.ifname ?? (); }
        }
    }
    ()
}

fn clients(device, ifname) {
    if ifname == () { return 0; }
    let out = device.ssh("iwinfo " + shell_quote(ifname) + " assoclist");
    let total = 0;
    for line in lines(out.stdout) {
        if regex_match(line, "^[0-9A-Fa-f]{2}(:[0-9A-Fa-f]{2}){5}") { total += 1; }
    }
    total
}

// ------------------------------------------------------- estado desejado

fn iface_name(ssid, band) {
    "nm_" + hash_hex(ssid, 8) + "_" + band
}

fn validate_fleet(fleet) {
    let seen = [];
    for n in fleet.networks {
        if seen.contains(n.ssid) { throw "O SSID " + n.ssid + " está repetido na rede."; }
        seen.push(n.ssid);
        let secret = n.key ?? "";
        if n.encryption != "none" && (secret.len() < 8 || secret.len() > 63) {
            throw "A senha da rede " + n.ssid + " precisa ter de 8 a 63 caracteres.";
        }
        if n.band_6g && n.encryption != "sae" {
            throw "A rede " + n.ssid + " em 6 GHz exige WPA3 (sae).";
        }
        if !n.band_2g && !n.band_5g && !n.band_6g {
            throw "A rede " + n.ssid + " não tem nenhuma banda marcada.";
        }
    }
    if fleet.mesh_enabled {
        let mesh_key = fleet.mesh_key ?? "";
        if fleet.mesh_id == "" { throw "Informe o identificador do mesh."; }
        if mesh_key.len() < 8 || mesh_key.len() > 63 {
            throw "A senha do mesh precisa ter de 8 a 63 caracteres.";
        }
    }
}

fn validate_local(local) {
    for band in ["2g", "5g", "6g"] {
        let ch = local["radio_" + band + "_channel"] ?? "";
        if ch != "" && ch != "auto" {
            let c = parse_int(ch);
            let ok = if band == "2g" { c >= 1 && c <= 14 } else if band == "5g" { c >= 32 && c <= 177 } else { c >= 1 && c <= 233 };
            if !ok { throw "O canal " + ch + " não existe em " + band_label(band) + "."; }
        }
        let ht = local["radio_" + band + "_htmode"] ?? "";
        if band == "2g" && (ht.contains("80") || ht.contains("160") || ht.contains("320")) {
            throw "A largura " + ht + " não existe em 2,4 GHz (use 20 ou 40).";
        }
        if band == "6g" && ht != "" && !ht.starts_with("HE") && !ht.starts_with("EHT") {
            throw "Em 6 GHz a largura precisa ser HE ou EHT.";
        }
    }
}

fn iface_options(n, radio) {
    let o = #{ device: radio, mode: "ap", network: n.network, ssid: n.ssid, encryption: n.encryption, disabled: "0" };
    if n.encryption != "none" { o.key = n.key; }
    if n.hidden { o.hidden = "1"; }
    if n.isolate { o.isolate = "1"; }
    if n.encryption == "sae" { o.ieee80211w = "2"; }
    if n.encryption == "sae-mixed" { o.ieee80211w = "1"; }
    if n.roaming && n.encryption != "none" {
        o.ieee80211r = "1";
        o.mobility_domain = hash_hex(n.ssid, 4);
        o.ft_over_ds = "0";
        o.ft_psk_generate_local = "1";
        o.ieee80211k = "1";
        o.rrm_neighbor_report = "1";
        o.rrm_beacon_report = "1";
        o.bss_transition = "1";
    }
    o
}

// O que este roteador deve ter: #{ ifaces: #{ nm_*: opções }, radios: #{ rádio: opções } }.
fn desired(device, radios) {
    let fleet = device.settings.fleet;
    let local = device.settings.device;
    validate_fleet(fleet);
    validate_local(local);
    let skip = local.disabled_networks ?? [];
    let ifaces = #{};
    let used = #{};
    for n in fleet.networks {
        if !n.enabled || skip.contains(n.ssid) { continue; }
        for band in ["2g", "5g", "6g"] {
            if !n["band_" + band] || !radios.contains(band) { continue; }
            let radio = radios[band];
            ifaces[iface_name(n.ssid, band)] = iface_options(n, radio);
            used[radio] = true;
        }
    }
    if fleet.mesh_enabled && radios.contains(fleet.mesh_band) {
        let radio = radios[fleet.mesh_band];
        ifaces["nm_mesh_" + fleet.mesh_band] = #{
            device: radio, mode: "mesh", mesh_id: fleet.mesh_id, encryption: "sae",
            key: fleet.mesh_key, network: fleet.mesh_network, mesh_fwding: "1",
            mesh_rssi_threshold: "0", disabled: "0"
        };
        used[radio] = true;
    }
    let radio_options = #{};
    for band in radios.keys() {
        let radio = radios[band];
        let prefix = "radio_" + band + "_";
        let o = #{};
        if local[prefix + "disabled"] ?? false {
            o.disabled = "1";
        } else if used.contains(radio) {
            o.disabled = "0";
            if fleet.country != "" { o.country = fleet.country; }
        }
        let channel = local[prefix + "channel"] ?? "";
        if channel != "" { o.channel = channel; }
        let htmode = local[prefix + "htmode"] ?? "";
        if htmode != "" { o.htmode = htmode; }
        let txpower = local[prefix + "txpower"] ?? ();
        if txpower != () { o.txpower = txpower.to_string(); }
        if o.len() > 0 { radio_options[radio] = o; }
    }
    #{ ifaces: ifaces, radios: radio_options }
}

// ---------------------------------------------------------------- plano

fn set_command(section, option, value) {
    "uci set wireless." + section + "." + option + "=" + shell_quote(value)
}

fn label_of(options) {
    if options.contains("mesh_id") { return "Mesh " + options.mesh_id; }
    options.ssid ?? ""
}

// Comandos que levam o roteador ao desejado, e o resumo legível.
fn plan(sections, want) {
    let commands = [];
    let changes = [];
    for name in want.ifaces.keys() {
        let opts = want.ifaces[name];
        if !sections.contains(name) {
            commands.push("uci set wireless." + name + "=wifi-iface");
            for k in opts.keys() { commands.push(set_command(name, k, opts[k])); }
            changes.push(#{ change: "criar", section: name, ssid: label_of(opts), detail: band_label(name.sub_string(name.len() - 2)) });
            continue;
        }
        let current = sections[name].options;
        let diff = [];
        for k in opts.keys() {
            if (current[k] ?? ()) != opts[k] {
                commands.push(set_command(name, k, opts[k]));
                diff.push(k);
            }
        }
        for k in current.keys() {
            if !opts.contains(k) {
                commands.push("uci delete wireless." + name + "." + k);
                diff.push(k);
            }
        }
        if diff.len() > 0 {
            changes.push(#{ change: "alterar", section: name, ssid: label_of(opts), detail: join_with(diff, ", ") });
        }
    }
    for name in sections.keys() {
        let section = sections[name];
        if name.starts_with("nm_") && section.kind == "wifi-iface" && !want.ifaces.contains(name) {
            commands.push("uci delete wireless." + name);
            changes.push(#{ change: "remover", section: name, ssid: label_of(section.options), detail: "" });
        }
    }
    for radio in want.radios.keys() {
        let opts = want.radios[radio];
        let current = sections[radio].options;
        let diff = [];
        for k in opts.keys() {
            if (current[k] ?? ()) != opts[k] {
                commands.push(set_command(radio, k, opts[k]));
                diff.push(k + "=" + opts[k]);
            }
        }
        if diff.len() > 0 {
            changes.push(#{ change: "rádio", section: radio, ssid: band_label(band_of(current)), detail: join_with(diff, ", ") });
        }
    }
    #{ commands: commands, changes: changes }
}

fn summary_of(changes) {
    let s = #{ create: 0, update: 0, remove: 0, radios: 0 };
    for c in changes {
        if c.change == "criar" { s.create += 1; }
        if c.change == "alterar" { s.update += 1; }
        if c.change == "remover" { s.remove += 1; }
        if c.change == "rádio" { s.radios += 1; }
    }
    s
}

fn section_state(sections, wanted, name) {
    if !sections.contains(name) { return "ausente"; }
    let current = sections[name].options;
    let opts = wanted[name];
    for k in opts.keys() { if (current[k] ?? ()) != opts[k] { return "divergente"; } }
    for k in current.keys() { if !opts.contains(k) { return "divergente"; } }
    "ok"
}

fn worst(states) {
    if states.contains("ausente") { return "ausente"; }
    if states.contains("divergente") { return "divergente"; }
    "ok"
}

// ---------------------------------------------------------- pacotes (DRY)

fn installed_wpad(device) {
    let found = "nenhum";
    for row in device.use_plugin("openwrt-packages", "list_packages", #{}) {
        if row.name.starts_with("wpad") { found = row.name; }
    }
    found
}

fn wpad_is_full(name) {
    name != "nenhum" && !name.contains("basic") && !name.contains("mini")
}

// ---------------------------------------------------------------- ações

fn detect(device, params) {
    let base = device.use_plugin("openwrt-packages", "detect", #{});
    let radios = radios_by_band(read_wireless(device));
    let bands = [];
    for band in radios.keys() { bands.push(band_label(band)); }
    let wpad = installed_wpad(device);
    #{
        firmware: base.firmware,
        model: base.model,
        package_manager: base.package_manager,
        radios: join_with(bands, ", "),
        wpad: wpad,
        roaming_ready: wpad_is_full(wpad),
        mesh_ready: wpad_is_full(wpad) || wpad.contains("mesh")
    }
}

fn status(device, params) {
    let sections = read_wireless(device);
    let radios = radios_by_band(sections);
    let want = desired(device, radios);
    let pending = plan(sections, want);
    let rt = runtime_status(device);
    let fleet = device.settings.fleet;
    let skip = device.settings.device.disabled_networks ?? [];

    let networks = [];
    for n in fleet.networks {
        if !n.enabled || skip.contains(n.ssid) {
            networks.push(#{ ssid: n.ssid, bands: "", state: "desativado", clients: 0 });
            continue;
        }
        let bands = [];
        let states = [];
        let total = 0;
        for band in ["2g", "5g", "6g"] {
            if !n["band_" + band] || !radios.contains(band) { continue; }
            bands.push(band_label(band));
            let name = iface_name(n.ssid, band);
            let state = section_state(sections, want.ifaces, name);
            states.push(state);
            if state == "ok" { total += clients(device, ifname_of(rt, name)); }
        }
        let state = if bands.len() == 0 { "sem_radio" } else { worst(states) };
        networks.push(#{ ssid: n.ssid, bands: join_with(bands, ", "), state: state, clients: total });
    }
    if fleet.mesh_enabled {
        let name = "nm_mesh_" + fleet.mesh_band;
        let state = if want.ifaces.contains(name) { section_state(sections, want.ifaces, name) } else { "sem_radio" };
        networks.push(#{ ssid: "Mesh " + fleet.mesh_id, bands: band_label(fleet.mesh_band), state: state, clients: 0 });
    }

    let radio_rows = [];
    for band in radios.keys() {
        let name = radios[band];
        let o = sections[name].options;
        let up = if rt.contains(name) { rt[name].up ?? false } else { false };
        radio_rows.push(#{
            radio: name, band: band_label(band), channel: o.channel ?? "auto",
            htmode: o.htmode ?? "", txpower: o.txpower ?? "", disabled: (o.disabled ?? "0") == "1", up: up
        });
    }
    let unmanaged = [];
    for name in sections.keys() {
        let section = sections[name];
        if section.kind == "wifi-iface" && !name.starts_with("nm_") {
            let o = section.options;
            unmanaged.push(#{ section: name, ssid: o.ssid ?? "", radio: o.device ?? "", mode: o.mode ?? "" });
        }
    }
    #{
        state: if pending.commands.len() == 0 { "sincronizado" } else { "pendente" },
        pending_changes: pending.changes.len(),
        networks: networks,
        radios: radio_rows,
        unmanaged: unmanaged
    }
}

fn preview(device, params) {
    let sections = read_wireless(device);
    let want = desired(device, radios_by_band(sections));
    let p = plan(sections, want);
    #{ summary: summary_of(p.changes), changes: p.changes, commands: p.commands }
}

fn apply(device, params) {
    let sections = read_wireless(device);
    let radios = radios_by_band(sections);
    let want = desired(device, radios);
    let p = plan(sections, want);
    if p.commands.len() == 0 {
        return "Nada a alterar: a configuração da rede já está aplicada neste roteador.";
    }
    let before = runtime_status(device);
    device.run("cp /etc/config/wireless /tmp/netmonitor-wireless.bak");
    let staged = device.ssh(join_with(p.commands, " && "));
    if staged.exit != 0 {
        device.ssh("uci revert wireless");
        throw "O roteador recusou a configuração (nada foi gravado):\n" + staged.stdout + staged.stderr;
    }
    device.run("uci commit wireless");
    let reload = device.ssh("wifi reload");
    let after = device.ssh("sleep 5; ubus call network.wireless status");

    let problems = [];
    let check = plan(read_wireless(device), want);
    if check.commands.len() > 0 { problems.push("a configuração gravada não confere com a desejada"); }
    if after.exit == 0 && trimmed(after.stdout) != "" {
        let now = json_parse(after.stdout);
        for radio in before.keys() {
            let was_up = before[radio].up ?? false;
            let off = want.radios.contains(radio) && (want.radios[radio].disabled ?? "0") == "1";
            let is_up = if now.contains(radio) { now[radio].up ?? false } else { false };
            if was_up && !off && !is_up { problems.push("o rádio " + radio + " estava no ar e não voltou"); }
        }
    }
    if problems.len() > 0 {
        device.ssh("cp /tmp/netmonitor-wireless.bak /etc/config/wireless && wifi reload");
        throw "A aplicação falhou (" + join_with(problems, "; ") + "). A configuração anterior foi restaurada.\n" + reload.stdout + reload.stderr;
    }
    let text = "Configuração aplicada: " + p.changes.len() + " alteração(ões).\n";
    for c in p.changes {
        text += "- " + c.change + " " + c.ssid + " (" + c.section + ")";
        if c.detail != "" { text += ": " + c.detail; }
        text += "\n";
    }
    text
}

fn parse_scan(text) {
    let cells = [];
    let current = ();
    for line in lines(text) {
        if line.starts_with("Cell ") {
            if current != () { cells.push(current); }
            current = #{ ssid: "", channel: 0, signal: -100 };
            continue;
        }
        if current == () { continue; }
        let essid = regex_capture(line, "ESSID: \"(.*)\"");
        if essid != () { current.ssid = essid; }
        let channel = regex_capture(line, "Channel: (\\d+)");
        if channel != () { current.channel = parse_int(channel); }
        let signal = regex_capture(line, "Signal: (-?\\d+) dBm");
        if signal != () { current.signal = parse_int(signal); }
    }
    if current != () { cells.push(current); }
    cells
}

fn scan(device, params) {
    let sections = read_wireless(device);
    let radios = radios_by_band(sections);
    let rt = runtime_status(device);
    let rows = [];
    for band in radios.keys() {
        let radio = radios[band];
        if !rt.contains(radio) { continue; }
        let ifaces = rt[radio].interfaces ?? [];
        if ifaces.len() == 0 { continue; }
        let ifname = ifaces[0].ifname ?? ();
        if ifname == () { continue; }
        let out = device.ssh("iwinfo " + shell_quote(ifname) + " scan");
        rows.push(#{
            radio: radio, band: band,
            channel: sections[radio].options.channel ?? "auto",
            neighbors: parse_scan(out.stdout)
        });
    }
    #{ radios: rows }
}

fn prepare_roaming(device, params) {
    let log = [];
    let wpad = installed_wpad(device);
    if wpad_is_full(wpad) {
        log.push("O " + wpad + " já suporta roaming 802.11r/k/v e mesh.");
    } else {
        if wpad != "nenhum" {
            log.push(device.use_plugin("openwrt-packages", "remove_package", #{ name: wpad }));
        }
        try {
            log.push(device.use_plugin("openwrt-packages", "install_package", #{ name: "wpad-mbedtls" }));
        } catch (err) {
            if wpad != "nenhum" {
                device.use_plugin("openwrt-packages", "install_package", #{ name: wpad });
            }
            throw "Não foi possível instalar o wpad completo; o " + wpad + " foi reinstalado.\n" + err;
        }
    }
    if device.settings.fleet.usteer {
        log.push(device.use_plugin("openwrt-packages", "install_package", #{ name: "usteer" }));
        device.run("/etc/init.d/usteer enable && /etc/init.d/usteer restart");
        log.push("usteer habilitado e iniciado.");
    }
    device.ssh("wifi reload");
    join_with(log, "\n")
}

// ------------------------------------------------- consolidado (sem rede)

fn overlaps(band, a, b) {
    let gap = a - b;
    if gap < 0 { gap = -gap; }
    if band == "2g" { gap < 5 } else { gap < 4 }
}

// Plano de canais: para cada rádio, o canal com menos interferência dos
// vizinhos (sinal acima de -100 dBm pesa) e dos outros roteadores da frota.
fn plan_channels(results, settings) {
    let own = [];
    for n in settings.fleet.networks { own.push(n.ssid); }
    let candidates = #{ "2g": [1, 6, 11], "5g": [36, 44, 149, 157] };
    let taken = #{ "2g": [], "5g": [] };
    let assignments = [];
    let patch = #{};
    for r in results {
        if r.status != "succeeded" || r.output == () { continue; }
        for radio in r.output.radios {
            let band = radio.band;
            if !candidates.contains(band) { continue; }
            let best = 0;
            let best_cost = 1000000;
            for ch in candidates[band] {
                let cost = 0;
                for n in radio.neighbors {
                    if !own.contains(n.ssid) && overlaps(band, ch, n.channel) {
                        let weight = n.signal + 100;
                        if weight > 0 { cost += weight; }
                    }
                }
                for t in taken[band] {
                    if overlaps(band, ch, t) { cost += 60; }
                }
                if cost < best_cost { best_cost = cost; best = ch; }
            }
            taken[band].push(best);
            let channel = best.to_string();
            assignments.push(#{ device: r.deviceName, band: band_label(band), current: radio.channel, channel: channel, interference: best_cost });
            if radio.channel != channel {
                let key = r.deviceId.to_string();
                if !patch.contains(key) { patch[key] = #{}; }
                patch[key]["radio_" + band + "_channel"] = channel;
            }
        }
    }
    let changed = patch.len();
    #{
        summary: if changed == 0 { "Os canais atuais já são os de menor interferência." } else { changed.to_string() + " roteador(es) com canal sugerido. Aceite o plano e aplique a configuração." },
        assignments: assignments,
        settings_patch: patch
    }
}
